#!/usr/bin/env node
/**
 * Build CEOVault Action structs for proposals.
 *
 * CEOVault validates actions at proposal time and execution time:
 * 1. value must be 0 (no native MON)
 * 2. USDC/$CEO: only approve(spender, amount); spender must be whitelisted
 * 3. Yield vaults: only deposit/mint/withdraw/redeem with receiver/owner = CEOVault
 * 4. Other whitelisted targets: any calldata
 *
 * Usage:
 *   node build-action.mjs approve USDC MORPHO_USDC_VAULT 5000000000
 *   node build-action.mjs deposit MORPHO_USDC_VAULT 5000000000
 *   node build-action.mjs noop
 *   node build-action.mjs --from-json '{"type":"approve","token":"USDC","spender":"MORPHO_USDC_VAULT","amount":"5000000000"}'
 *
 * Output: JSON array of Action objects { target, value, data } (value always 0)
 */

import { encodeFunctionData, parseAbi } from "viem";
import {
  CEO_VAULT,
  USDC,
  CEO_TOKEN,
  MORPHO_USDC_VAULT,
  WHITELISTED_TARGETS,
} from "./ceo-config.mjs";

const ERC20_ABI = parseAbi([
  "function approve(address spender, uint256 amount) returns (bool)",
]);

const ERC4626_ABI = parseAbi([
  "function deposit(uint256 assets, address receiver) returns (uint256)",
  "function mint(uint256 shares, address receiver) returns (uint256)",
  "function withdraw(uint256 assets, address receiver, address owner) returns (uint256)",
  "function redeem(uint256 shares, address receiver, address owner) returns (uint256)",
]);

const TARGET_MAP = {
  USDC,
  CEO_TOKEN,
  MORPHO_USDC_VAULT,
  ...WHITELISTED_TARGETS,
};

/**
 * Build a single Action for CEOVault.
 * @param {object} spec - { type, token?, target?, spender?, amount?, shares?, data? }
 * @returns {{ target: string, value: bigint, data: string }}
 */
export function buildAction(spec) {
  const { type } = spec;
  const value = 0n;

  switch (type) {
    case "approve": {
      const token = resolveAddress(spec.token);
      const spender = resolveAddress(spec.spender);
      const amount = BigInt(spec.amount ?? 0);
      const data = encodeFunctionData({
        abi: ERC20_ABI,
        functionName: "approve",
        args: [spender, amount],
      });
      return { target: token, value, data };
    }

    case "deposit": {
      const vault = resolveAddress(spec.target ?? spec.vault);
      const assets = BigInt(spec.amount ?? spec.assets ?? 0);
      const data = encodeFunctionData({
        abi: ERC4626_ABI,
        functionName: "deposit",
        args: [assets, CEO_VAULT],
      });
      return { target: vault, value, data };
    }

    case "mint": {
      const vault = resolveAddress(spec.target ?? spec.vault);
      const shares = BigInt(spec.shares ?? 0);
      const data = encodeFunctionData({
        abi: ERC4626_ABI,
        functionName: "mint",
        args: [shares, CEO_VAULT],
      });
      return { target: vault, value, data };
    }

    case "withdraw": {
      const vault = resolveAddress(spec.target ?? spec.vault);
      const assets = BigInt(spec.amount ?? spec.assets ?? 0);
      const data = encodeFunctionData({
        abi: ERC4626_ABI,
        functionName: "withdraw",
        args: [assets, CEO_VAULT, CEO_VAULT],
      });
      return { target: vault, value, data };
    }

    case "redeem": {
      const vault = resolveAddress(spec.target ?? spec.vault);
      const shares = BigInt(spec.shares ?? 0);
      const data = encodeFunctionData({
        abi: ERC4626_ABI,
        functionName: "redeem",
        args: [shares, CEO_VAULT, CEO_VAULT],
      });
      return { target: vault, value, data };
    }

    case "custom":
    case "adapter": {
      const target = resolveAddress(spec.target);
      const data = spec.data?.startsWith("0x")
        ? spec.data
        : `0x${Buffer.from(spec.data, "hex").toString("hex")}`;
      return { target, value, data };
    }

    default:
      throw new Error(`Unknown action type: ${type}`);
  }
}

function resolveAddress(key) {
  if (typeof key !== "string") throw new Error("Address key must be string");
  const addr = TARGET_MAP[key] ?? (key.startsWith("0x") ? key : null);
  if (!addr) throw new Error(`Unknown address key: ${key}`);
  return addr;
}

/**
 * Build no-op proposal (approve 0 to a yield vault). Useful for "do nothing" epochs.
 */
export function buildNoopActions() {
  return [
    buildAction({
      type: "approve",
      token: "USDC",
      spender: "MORPHO_USDC_VAULT",
      amount: 0,
    }),
  ];
}

/**
 * Build deploy-to-yield actions: approve USDC to vault, then deposit.
 * @param {string|number|bigint} amount - USDC amount (6 decimals)
 * @param {string} [yieldVault] - Yield vault key (default MORPHO_USDC_VAULT)
 */
export function buildDeployActions(amount, yieldVault = "MORPHO_USDC_VAULT") {
  const amt = BigInt(amount);
  return [
    buildAction({
      type: "approve",
      token: "USDC",
      spender: yieldVault,
      amount: amt,
    }),
    buildAction({
      type: "deposit",
      target: yieldVault,
      amount: amt,
    }),
  ];
}

/**
 * Convert actions to format suitable for viem/contract call.
 * CEOVault expects { target, value, data } with value as bigint.
 */
export function toContractFormat(actions) {
  return actions.map((a) => ({
    target: a.target,
    value: BigInt(a.value ?? 0),
    data: typeof a.data === "string" ? a.data : `0x${a.data.toString("hex")}`,
  }));
}

// ── CLI ──

function parseArgs(argv) {
  const args = {};
  for (let i = 2; i < argv.length; i++) {
    const t = argv[i];
    if (t === "--from-json" && argv[i + 1]) {
      return { fromJson: argv[i + 1] };
    }
    if (t.startsWith("--")) {
      const k = t.slice(2);
      args[k] = argv[i + 1] ?? true;
      if (argv[i + 1]) i++;
      continue;
    }
    if (!args._) args._ = [];
    args._.push(t);
  }
  return args;
}

async function main() {
  const args = parseArgs(process.argv);

  let actions;

  if (args.fromJson) {
    const spec = JSON.parse(args.fromJson);
    actions = Array.isArray(spec) ? spec.map((s) => buildAction(s)) : [buildAction(spec)];
  } else {
    const [cmd, ...rest] = args._ ?? [];

    if (cmd === "noop") {
      actions = buildNoopActions();
    } else if (cmd === "deploy") {
      const amount = rest[0] ?? "0";
      const vault = rest[1] ?? "MORPHO_USDC_VAULT";
      actions = buildDeployActions(amount, vault);
    } else if (cmd === "approve") {
      const [token, spender, amount] = rest;
      actions = [buildAction({ type: "approve", token, spender, amount: amount ?? 0 })];
    } else if (cmd === "deposit") {
      const [vault, amount] = rest;
      actions = [buildAction({ type: "deposit", target: vault, amount: amount ?? 0 })];
    } else if (cmd === "withdraw") {
      const [vault, amount] = rest;
      actions = [buildAction({ type: "withdraw", target: vault, amount: amount ?? 0 })];
    } else if (cmd === "redeem") {
      const [vault, shares] = rest;
      actions = [buildAction({ type: "redeem", target: vault, shares: shares ?? 0 })];
    } else {
      console.error(`Usage:
  node build-action.mjs noop
  node build-action.mjs deploy <amount> [yieldVault]
  node build-action.mjs approve <token> <spender> <amount>
  node build-action.mjs deposit <yieldVault> <amount>
  node build-action.mjs withdraw <yieldVault> <amount>
  node build-action.mjs redeem <yieldVault> <shares>
  node build-action.mjs --from-json '<JSON>'

Examples:
  node build-action.mjs noop
  node build-action.mjs deploy 5000000000
  node build-action.mjs approve USDC MORPHO_USDC_VAULT 5000000000
  node build-action.mjs deposit MORPHO_USDC_VAULT 5000000000`);
      process.exit(1);
    }
  }

  const formatted = toContractFormat(actions);
  console.log(JSON.stringify(formatted, (_, v) => (typeof v === "bigint" ? v.toString() : v), 2));
}

// Only run CLI when executed directly (not when imported)
if (process.argv[1]?.includes("build-action.mjs")) {
  main().catch((err) => {
    console.error(err.message);
    process.exit(1);
  });
}

#!/usr/bin/env node
/**
 * Build a full CEOVault proposal (actions + proposalURI) for registerProposal.
 *
 * Reads actions from:
 *   - --file <path>  JSON file with array of action specs
 *   - --stdin        JSON from stdin
 *   - --noop         Use no-op actions (approve 0)
 *   - --deploy <amount> [vault]  Deploy USDC to yield vault
 *
 * Output: JSON with { actions, proposalURI, proposalHash } for submit-proposal.mjs
 *
 * Usage:
 *   node build-proposal.mjs --noop --uri "https://example.com/proposal-1"
 *   node build-proposal.mjs --deploy 5000000000 --uri "ipfs://Qm..."
 *   node build-proposal.mjs --file proposal.json --uri "https://..."
 *   echo '[{"type":"approve","token":"USDC","spender":"MORPHO_USDC_VAULT","amount":"0"}]' | node build-proposal.mjs --stdin --uri "https://..."
 */

import { keccak256, encodeAbiParameters, parseAbiParameters } from "viem";
import { readFile } from "node:fs/promises";
import { buildAction, buildNoopActions, buildDeployActions, toContractFormat } from "./build-action.mjs";

const ACTION_ABI = parseAbiParameters("(address target, uint256 value, bytes data)[]");

/**
 * Compute proposalHash = keccak256(abi.encode(actions))
 * Must match at execution time.
 */
export function computeProposalHash(actions) {
  const encoded = encodeAbiParameters(ACTION_ABI, [actions]);
  return keccak256(encoded);
}

/**
 * Build proposal from action specs.
 * @param {Array<object>} specs - Array of action specs for buildAction
 * @param {string} proposalURI - Off-chain URI
 * @returns {{ actions, proposalURI, proposalHash }}
 */
export function buildProposal(specs, proposalURI) {
  const actions = specs.map((s) => buildAction(s));
  const formatted = toContractFormat(actions);
  const proposalHash = computeProposalHash(formatted);
  return { actions: formatted, proposalURI, proposalHash };
}

async function main() {
  const args = parseArgs(process.argv);
  const uri = args.uri ?? args.proposalUri ?? "https://moltiverse.xyz/proposal";

  let actions;

  if (args.noop) {
    actions = buildNoopActions();
  } else if (args.deploy) {
    const amount = args.deploy;
    const vault = args.vault ?? "MORPHO_USDC_VAULT";
    actions = buildDeployActions(amount, vault);
  } else if (args.file) {
    const raw = await readFile(args.file, "utf-8");
    const specs = JSON.parse(raw);
    if (!Array.isArray(specs)) throw new Error("File must contain JSON array of action specs");
    actions = specs.map((s) => buildAction(s));
  } else if (args.stdin) {
    let input = "";
    for await (const chunk of process.stdin) input += chunk;
    const specs = JSON.parse(input || "[]");
    actions = Array.isArray(specs) ? specs.map((s) => buildAction(s)) : [buildAction(specs)];
  } else {
    console.error(`Usage:
  node build-proposal.mjs --noop --uri <proposalURI>
  node build-proposal.mjs --deploy <amount> [--vault MORPHO_USDC_VAULT] --uri <proposalURI>
  node build-proposal.mjs --file <path> --uri <proposalURI>
  node build-proposal.mjs --stdin --uri <proposalURI>

Required: --uri (or --proposalUri) with off-chain proposal description URL`);
    process.exit(1);
  }

  const formatted = toContractFormat(actions);
  const proposalHash = computeProposalHash(formatted);

  const out = {
    actions: formatted.map((a) => ({
      target: a.target,
      value: a.value.toString(),
      data: a.data,
    })),
    proposalURI: uri,
    proposalHash,
  };

  console.log(JSON.stringify(out, null, 2));
}

function parseArgs(argv) {
  const args = {};
  for (let i = 2; i < argv.length; i++) {
    const t = argv[i];
    if (t.startsWith("--")) {
      const k = t.slice(2).replace(/-([a-z])/g, (_, c) => c.toUpperCase());
      const next = argv[i + 1];
      args[k] = next && !next.startsWith("--") ? next : true;
      if (next && !next.startsWith("--")) i++;
    }
  }
  return args;
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

/**
 * CEO Protocol (CEOVault) configuration for Monad mainnet.
 * Used by build-action, build-proposal, and submit-proposal scripts.
 */

import { getAddress } from "viem";

// Monad mainnet addresses
export const CEO_VAULT = getAddress("0xdb60410d2dEef6110e913dc58BBC08F74dc611c4");
export const USDC = getAddress("0x754704Bc059F8C67012fEd69BC8A327a5aafb603");
export const CEO_TOKEN = getAddress("0xCA26f09831A15dCB9f9D47CE1cC2e3B086467777");

// Yield vaults (ERC-4626) — must be added via addYieldVault
export const MORPHO_USDC_VAULT = getAddress("0xbeEFf443C3CbA3E369DA795002243BeaC311aB83");

// Whitelisted targets for approve() spenders and adapter calls
export const WHITELISTED_TARGETS = {
  MORPHO_USDC_VAULT,
  UNISWAP_UNIVERSAL_ROUTER: getAddress("0x0D97Dc33264bfC1c226207428A79b26757fb9dc3"),
  UNISWAP_POOL_MANAGER: getAddress("0x188d586Ddcf52439676Ca21A244753fA19F9Ea8e"),
};

import {
  createPublicClient,
  createWalletClient,
  defineChain,
  getAddress,
  http,
} from "viem";
import { privateKeyToAccount } from "viem/accounts";

export const MAINNET_IDENTITY = "0x8004A169FB4a3325136EB29fA0ceB6D2e539a432";

export const NETWORKS = {
  "monad-mainnet": { chainId: 143, registry: MAINNET_IDENTITY },
  "monad-testnet": { chainId: 10143, registry: MAINNET_IDENTITY },
};

export function parseArgs(argv) {
  const args = {};
  for (let i = 2; i < argv.length; i += 1) {
    const token = argv[i];
    if (!token.startsWith("--")) continue;
    const key = token.slice(2);
    const next = argv[i + 1];
    if (!next || next.startsWith("--")) {
      args[key] = true;
      continue;
    }
    args[key] = next;
    i += 1;
  }
  return args;
}

export function requiredEnv(name) {
  const value = process.env[name];
  if (!value || value.trim() === "") throw new Error(`Missing required env var: ${name}`);
  return value.trim();
}

export function resolveNetwork(args = {}) {
  const envChainId = Number(process.env.MONAD_CHAIN_ID ?? "143");
  const networkName = args.network ?? "monad-mainnet";
  const fromMap = NETWORKS[networkName];
  const chainId = args.chainId ? Number(args.chainId) : fromMap?.chainId ?? envChainId;
  const rpcUrl = args.rpcUrl ?? process.env.MONAD_RPC_URL;
  if (!rpcUrl) throw new Error("Missing RPC URL. Pass --rpcUrl or set MONAD_RPC_URL.");
  const registry = getAddress(args.registry ?? fromMap?.registry ?? MAINNET_IDENTITY);
  return { networkName, chainId, rpcUrl, registry };
}

export function createClients(params) {
  const account = privateKeyToAccount(requiredEnv("AGENT_PRIVATE_KEY"));
  const chain = defineChain({
    id: params.chainId,
    name: params.networkName,
    nativeCurrency: { name: "MON", symbol: "MON", decimals: 18 },
    rpcUrls: { default: { http: [params.rpcUrl] } },
  });
  const transport = http(params.rpcUrl);
  const publicClient = createPublicClient({ chain, transport });
  const walletClient = createWalletClient({ chain, transport, account });
  return { account, publicClient, walletClient, chain };
}

